CREATE TABLE fiscal_classifications (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, ncm VARCHAR(8) NOT NULL CHECK (ncm ~ '^[0-9]{8}$'), detail TEXT NOT NULL, created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE fiscal_operations (id TEXT PRIMARY KEY, classification_id TEXT NOT NULL REFERENCES fiscal_classifications(id) ON DELETE RESTRICT, code VARCHAR(4) NOT NULL CHECK (code ~ '^[0-9]{4}$'), label TEXT NOT NULL, UNIQUE(classification_id, code));
ALTER TABLE "Category" ADD COLUMN fiscal_operation_id TEXT REFERENCES fiscal_operations(id) ON DELETE RESTRICT;
ALTER TABLE "Product" ADD COLUMN fiscal_operation_id TEXT REFERENCES fiscal_operations(id) ON DELETE RESTRICT;
ALTER TABLE fiscal_classifications ENABLE ROW LEVEL SECURITY;
ALTER TABLE fiscal_classifications FORCE ROW LEVEL SECURITY;
ALTER TABLE fiscal_operations ENABLE ROW LEVEL SECURITY;
ALTER TABLE fiscal_operations FORCE ROW LEVEL SECURITY;
CREATE POLICY fiscal_catalog_read ON fiscal_classifications FOR SELECT TO delivery_app USING (true);
CREATE POLICY fiscal_catalog_write ON fiscal_classifications FOR INSERT TO delivery_app WITH CHECK (app_security_staff());
CREATE POLICY fiscal_operation_read ON fiscal_operations FOR SELECT TO delivery_app USING (true);
CREATE POLICY fiscal_operation_write ON fiscal_operations FOR INSERT TO delivery_app WITH CHECK (app_security_staff());
GRANT SELECT, INSERT ON fiscal_classifications, fiscal_operations TO delivery_app;
